def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    from collections import Counter
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    pairs = set()
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == bg:
                continue
            for dr, dc in ((1, 1), (1, -1)):
                rr, cc = r + dr, c + dc
                if 0 <= rr < h and 0 <= cc < w and grid[rr][cc] == color:
                    pairs.add((r, c, dr, dc, color))
    for r, c, dr, dc, color in pairs:
        for sr, sc, step in ((r, c, -1), (r + dr, c + dc, 1)):
            rr, cc = sr + step * dr, sc + step * dc
            while 0 <= rr < h and 0 <= cc < w and out[rr][cc] == bg:
                out[rr][cc] = color
                rr += step * dr
                cc += step * dc
    return out
